 function isotonicFit(data){if(data.length<3)return null;const mp=new Map();for(const d of data){const k=d.rain,w=d._rw??d._w??1;if(!mp.has(k))mp.set(k,{x:k,sw:0,sy:0});const o=mp.get(k);o.sw+=w;o.sy+=w*d.depth}const pts=[...mp.values()].sort((a,b)=>a.x-b.x).map(o=>({lo:o.x,hi:o.x,sw:o.sw,avg:o.sy/o.sw}));if(pts.length<3)return null;const blocks=[];for(const p of pts){blocks.push({...p});while(blocks.length>=2&&blocks[blocks.length-2].avg>blocks[blocks.length-1].avg){const b=blocks.pop(),a=blocks.pop(),sw=a.sw+b.sw;blocks.push({lo:a.lo,hi:b.hi,sw,avg:(a.avg*a.sw+b.avg*b.sw)/sw})}}function predict(x){if(x<=blocks[0].lo)return blocks[0].avg;if(x>=blocks[blocks.length-1].hi)return blocks[blocks.length-1].avg;for(let i=0;i<blocks.length;i++){const b=blocks[i];if(x>=b.lo&&x<=b.hi)return b.avg;const n=blocks[i+1];if(n&&x>b.hi&&x<n.lo){const t=(x-b.hi)/(n.lo-b.hi);return b.avg+t*(n.avg-b.avg)}}return blocks[blocks.length-1].avg}return {blocks,predict}}
 function sse(data){if(!data.length)return 0;let sw=0,sy=0;for(const d of data){const w=d._rw??d._w??1;sw+=w;sy+=w*d.depth}const m=sy/sw;return data.reduce((s,d)=>s+(d._rw??d._w??1)*(d.depth-m)**2,0)}
 function treeFit(data,maxDepth=2,minLeaf=2){if(data.length<5)return null;function build(ds,depth){let sw=0,sy=0;for(const d of ds){const w=d._rw??d._w??1;sw+=w;sy+=w*d.depth}const value=sy/sw;if(depth>=maxDepth||ds.length<minLeaf*2)return {leaf:true,value};const xs=[...new Set(ds.map(d=>d.rain))].sort((a,b)=>a-b);let best=null;for(let i=0;i<xs.length-1;i++){const cut=(xs[i]+xs[i+1])/2,L=ds.filter(d=>d.rain<=cut),R=ds.filter(d=>d.rain>cut);if(L.length<minLeaf||R.length<minLeaf)continue;const loss=sse(L)+sse(R);if(!best||loss<best.loss)best={cut,L,R,loss}}if(!best)return {leaf:true,value};return {leaf:false,cut:best.cut,value,left:build(best.L,depth+1),right:build(best.R,depth+1)}}const root=build(data,0);return {root,predict(x){let n=root;while(!n.leaf)n=x<=n.cut?n.left:n.right;return n.value}}}
 function histPredict(data,rain){const near=data.slice().sort((a,b)=>Math.abs(a.rain-rain)-Math.abs(b.rain-rain)).slice(0,Math.min(4,data.length));let sw=0,sy=0;for(const d of near){const w=(d._rw??d._w??1)/(Math.abs(d.rain-rain)+8);sw+=w;sy+=w*d.depth}return sw?sy/sw:NaN}
 function knnPredict(data,rain,k=3){const near=data.slice().sort((a,b)=>Math.abs(a.rain-rain)-Math.abs(b.rain-rain)).slice(0,Math.min(k,data.length));let sw=0,sy=0;for(const d of near){const w=(d._rw??d._w??1)/(Math.abs(d.rain-rain)+5);sw+=w;sy+=w*d.depth}return sw?sy/sw:NaN}
 function fitKind(kind,train){const d=withRobustWeights(train);if(kind==='hist')return {predict:x=>histPredict(d,x)};if(kind==='linear')return weightedLinFit(d);if(kind==='knn')return {predict:x=>knnPredict(d,x,Math.min(3,d.length))};if(kind==='theil')return theilFit(d);if(kind==='iso')return isotonicFit(d);if(kind==='tree')return treeFit(d,2,2);if(kind==='quad')return weightedQuadFit(d);return null}
 function metrics(errs){const e=errs.filter(Number.isFinite);if(e.length<2)return null;return {mae:mean(e.map(Math.abs)),rmse:Math.sqrt(mean(e.map(x=>x*x))),n:e.length}}
 function loo(data,kind){if(data.length<3)return null;const errs=[];for(let i=0;i<data.length;i++){const tr=data.filter((_,j)=>j!==i),f=fitKind(kind,tr);if(!f)continue;const p=f.predict(data[i].rain);if(Number.isFinite(p))errs.push(p-data[i].depth)}return errs.length>=2?metrics(errs):null}
 function r2(data,pred){if(data.length<2)return NaN;const ym=mean(data.map(x=>x.depth)),ss=data.reduce((s,x)=>s+(x.depth-ym)**2,0);if(ss<1e-9)return NaN;const er=data.reduce((s,x)=>{const p=pred(x.rain);return s+(x.depth-p)**2},0);return 1-er/ss}
 function globalFit(data){const d=withRobustWeights(data.map(x=>({...x,_w:(x._w??1)/Math.max(1,DATE_N[x.date]||1)})));return weightedLinFit(d,x=>x._rw??x._w??1)}
 function streetBias(train,street,fit){const s=train.filter(x=>normStreet(x.street)===normStreet(street));if(!s.length)return 0;let sw=0,sr=0;for(const x of s){const w=x._w??1;sw+=w;sr+=w*(x.depth-fit.predict(x.rain))}const raw=sw?sr/sw:0,shrink=s.length/(s.length+3);return raw*shrink}
 function hierPredict(train,street,rain){const f=globalFit(train);if(!f)return NaN;return f.predict(rain)+streetBias(train,street,f)}
 function hierCV(street,data){const dates=[...new Set(data.map(x=>x.date))],errs=[];for(const dt of dates){const tr=GLOBAL.filter(x=>x.date!==dt),tests=data.filter(x=>x.date===dt);if(tr.length<8)continue;for(const t of tests){const p=hierPredict(tr,street,t.rain);if(Number.isFinite(p))errs.push(p-t.depth)}}return metrics(errs)}
 function mlrFit(data){if(data.length<3)return null;let S0=0,Sx=0,St=0,Sxx=0,Stt=0,Sxt=0,Sy=0,Sxy=0,Sty=0;for(const d of data){const w=d._w??1,x=d.rain,t=d.tide,y=d.depth;S0+=w;Sx+=w*x;St+=w*t;Sxx+=w*x*x;Stt+=w*t*t;Sxt+=w*x*t;Sy+=w*y;Sxy+=w*x*y;Sty+=w*t*y}const c=solve([[S0,Sx,St],[Sx,Sxx,Sxt],[St,Sxt,Stt]],[Sy,Sxy,Sty]);return c?{coef:c,predict:(r,t)=>c[0]+c[1]*r+c[2]*t}:null}
 const TRIPLE=GLOBAL.filter(x=>x.tide!=null),TRIPLE_DATES=[...new Set(TRIPLE.map(x=>x.date))];
 function evidenceBand(street,rain){const ns=normStreet(resolveStreet(street));const e=ALL.filter(r=>normStreet(r.street)===ns&&finite(r.rain)&&(finite(r.depth)||finite(r.depth_min)||finite(r.depth_max))&&String(r.derived||'')!=='Có').map(r=>({r,dist:Math.abs(Number(r.rain)-rain)})).sort((a,b)=>a.dist-b.dist).slice(0,4).map(x=>x.r);if(!e.length)return null;const lows=e.map(r=>finite(r.depth)?Number(r.depth):finite(r.depth_min)?Number(r.depth_min):NaN).filter(Number.isFinite),highs=e.map(r=>finite(r.depth)?Number(r.depth):finite(r.depth_max)?Number(r.depth_max):NaN).filter(Number.isFinite);return {lower:lows.length?Math.min(...lows):NaN,upper:highs.length?Math.max(...highs):NaN,n:e.length}}
 function model(id,name,available,pred,cv,n,note,formula,extra={}){return {id,name,available:!!available,pred:Number.isFinite(pred)?Math.max(0,pred):NaN,metrics:cv,n,note,formula,ensembleEligible:extra.ensembleEligible!==false,reliability:extra.reliability??1,validation:extra.validation||'LOOCV',tag:extra.tag||null,r2:extra.r2}}
 const CACHE=new Map();
 function predict(street,rain,tide=null){
   street=resolveStreet(street);rain=Math.max(0,num(rain)||0);tide=finite(tide)?Number(tide):null;const key=normStreet(street)+'|'+rain+'|'+(tide??'NA');if(CACHE.has(key))return CACHE.get(key);
   const data=dedupCore(ALL,street), rains=data.map(x=>x.rain),minRain=rains.length?Math.min(...rains):NaN,maxRain=rains.length?Math.max(...rains):NaN,inside=data.length>0&&rain>=minRain&&rain<=maxRain;
   const models=[];
   function local(kind,id,name,minN,reliability,formula){const f=data.length>=minN?fitKind(kind,data):null,ok=!!f&&inside,p=ok?f.predict(rain):NaN,cv=ok?loo(data,kind):null;let note=data.length<minN?`Cần ≥${minN} sự kiện độc lập Tuyến × Ngày.`:!inside?`Ngoài range mưa ${minRain.toFixed(1)}–${maxRain.toFixed(1)} mm; không ngoại suy.`:'Khử lặp theo Tuyến × Ngày; có trọng số chất lượng nguồn.';const m=model(id,name,ok,p,cv,data.length,note,formula,{reliability,validation:'LOOCV'});if(ok&&f&&['linear','theil','iso','tree','quad'].includes(kind))m.r2=r2(data,x=>f.predict(x));models.push(m);return m}
   const mh=local('hist','hist','Source-aware Historical Similarity',2,.80,'weighted nearest events');
   const ml=local('linear','linear','Robust Weighted Linear Regression',3,1.00,'depth = b0 + b1×rain');
   const mk=local('knn','knn','Source-aware KNN Regression',3,.85,'k-nearest weighted by source + rain distance');
   const mt=local('theil','theil','Theil–Sen Robust Regression',4,1.05,'median pairwise slope');
   const mi=local('iso','iso','Isotonic Monotonic Regression',4,1.00,'non-decreasing depth vs rain (PAVA)');
   const mr=local('tree','tree','Shallow CART Regression Tree',5,.72,'depth≤2, min leaf=2');
   const mq=local('quad','quad','Weighted Quadratic Regression',6,.65,'depth = b0+b1×rain+b2×rain²');
   if(mq.available&&mq.metrics&&ml.metrics&&mq.metrics.mae>ml.metrics.mae*1.25){mq.ensembleEligible=false;mq.tag='DIAGNOSTIC';mq.note+=' CV kém hơn linear >25%, loại khỏi Ensemble.'}
   const gf=GLOBAL.length>=8?globalFit(GLOBAL):null,globalRains=GLOBAL.map(x=>x.rain),gmin=Math.min(...globalRains),gmax=Math.max(...globalRains),hOk=!!gf&&data.length>=1&&rain>=gmin&&rain<=gmax,hPred=hOk?hierPredict(GLOBAL,street,rain):NaN,hcv=hOk?hierCV(street,data):null;
   models.push(model('hier','Hierarchical Street + City',hOk,hPred,hcv,data.length,hOk?`Global event-balanced (${[...new Set(GLOBAL.map(x=>x.date))].length} ngày sự kiện) + street bias shrinkage.`:data.length<1?'Cần ≥1 sự kiện core của tuyến.':'Ngoài range mưa toàn cục.', 'global rain model + shrunk street residual',{reliability:.72,validation:'Group-by-Date CV',tag:'EVENT-BALANCED'}));
   const tf=TRIPLE.length>=6?mlrFit(TRIPLE):null,tOk=!!tf&&tide!=null&&TRIPLE_DATES.length>=2&&rain>=Math.min(...TRIPLE.map(x=>x.rain))&&rain<=Math.max(...TRIPLE.map(x=>x.rain)),tPred=tOk?tf.predict(rain,tide):NaN;
   models.push(model('tide','Rain + Tide Context Regression',tOk,tPred,null,TRIPLE.length,tide==null?`Nhập triều để xem; hiện có ${TRIPLE.length} cặp nhưng chỉ ${TRIPLE_DATES.length} ngày độc lập.`:`Chỉ ${TRIPLE_DATES.length} ngày sự kiện độc lập có đủ rain+tide+depth; KHÔNG đưa vào Ensemble.`,'depth=b0+b1×rain+b2×tide',{ensembleEligible:false,reliability:.3,validation:'Context only',tag:'CONTEXT ONLY'}));
   const eligible=models.filter(m=>m.available&&m.ensembleEligible&&Number.isFinite(m.pred));
   const rawW=eligible.map(m=>{const mae=m.metrics?.mae;const cvw=Number.isFinite(mae)?1/(mae+3):.08;return {m,w:m.reliability*cvw}});let ensemble=NaN,weights=[];
   if(rawW.length>=2){const sum=rawW.reduce((s,x)=>s+x.w,0);weights=rawW.map(x=>({id:x.m.id,w:x.w/sum}));ensemble=rawW.reduce((s,x)=>s+x.m.pred*x.w,0)/sum}
   const preds=eligible.map(m=>m.pred),band=preds.length?{low:preds.length<=4?Math.min(...preds):quant(preds,.10),high:preds.length<=4?Math.max(...preds):quant(preds,.90)}:null,spread=preds.length>=2?Math.sqrt(mean(preds.map(x=>(x-mean(preds))**2))):NaN,best=eligible.filter(m=>m.metrics&&Number.isFinite(m.metrics.mae)).sort((a,b)=>a.metrics.mae-b.metrics.mae)[0]||null;
   let confidence='LOW';if(Number.isFinite(ensemble)){const rel=spread/Math.max(10,ensemble);if(eligible.length>=4&&data.length>=4&&best&&best.metrics.mae<=12&&rel<=.30)confidence='HIGH';else if(eligible.length>=2&&data.length>=2&&rel<=.55)confidence='MEDIUM'}
   const depth=Number.isFinite(ensemble)?Math.max(0,ensemble):NaN,risk=!Number.isFinite(depth)?'UNKNOWN':depth>=40?'HIGH':depth>=20?'MEDIUM':'LOW',evBand=evidenceBand(street,rain);
   const result={street,rain,tide,startYear:START_YEAR,dataN:data.length,coreN:data.length,minRain,maxRain,inside,models,availableN:eligible.length,ensemble:depth,risk,weights,confidence,consensusBand:band,modelSpread:spread,evidenceBand:evBand,globalIndependentDates:[...new Set(GLOBAL.map(x=>x.date))].length,tideIndependentDates:TRIPLE_DATES.length,audit:AUDIT};
   CACHE.set(key,result);return result;
 }
 function rows(street){return dedupCore(ALL,street).map(r=>({date:r.date,street:r.street,rain:r.rain,depth:r.depth,tide:r.tide,cause:r.cause,source_url:r.url,rain_grade:r.quality,source_level:r.source_level,weight:r._w}))}
 function bestMetrics(result){const a=result.models.filter(m=>m.available&&m.ensembleEligible&&m.metrics&&Number.isFinite(m.metrics.mae));return a.length?a.slice().sort((x,y)=>x.metrics.mae-y.metrics.mae)[0]:null}
 window.FG15MultiModel={predict,rows,bestMetrics,START_YEAR,AUDIT,GLOBAL,resolveStreet};
